'use strict';
const state={style:'premium-minimal',view:'card',compare:false,motion:false,compareStyles:['premium-minimal','blueprint','glassmorphism'],search:'',category:'all'};
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function notify(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
function action(label,mini,mode='lesson'){return mini?`<span class="demo-action">${label}<span aria-hidden="true">↗</span></span>`:`<button type="button" class="demo-action" data-demo="${mode}">${label}<span aria-hidden="true">↗</span></button>`;}
function renderCard(mini=false){return `<article class="demo-panel demo-card"><div class="demo-kicker"><span>AI AT WORK</span><span class="demo-tag">SELF-PACED</span></div><div class="topic-icon" aria-hidden="true">↗</div><h3>Turn meeting notes<br>into action.</h3><p>A practical guide to clear next steps, visible owners, and better follow-through.</p><div class="demo-meta"><span>◷ &nbsp;12 min</span><span>01 / Foundation</span></div>${action('View lesson',mini)}</article>`;}
function renderPage(){return `<article class="demo-panel demo-page"><div class="demo-nav"><strong>THE LEARNING ROOM</strong><span>01 / AI at work</span></div><div class="demo-kicker"><span>A PRACTICAL FIELD GUIDE</span><span>12 MIN READ</span></div><h3>From notes<br>to next steps.</h3><p>Make the work after the meeting as clear as the conversation.</p><div class="page-cols"><div><h4>What you’ll practice</h4><ul class="demo-list"><li><span aria-hidden="true">01</span>Separate decisions from discussion.</li><li><span aria-hidden="true">02</span>Identify actions and confirmed owners.</li><li><span aria-hidden="true">03</span>Flag gaps instead of guessing.</li></ul></div><aside class="callout"><h4>A useful boundary</h4><p>Your notes are the source. If an owner or deadline is missing, mark it for confirmation.</p></aside></div><div class="page-bottom">${action('Try the practice',false,'practice')}<small>Fictional learning example<br>No real work data</small></div></article>`;}
function renderDashboard(){return `<article class="demo-panel demo-dashboard"><div class="demo-nav"><strong>THE LEARNING ROOM</strong><span>YOUR WORKSPACE</span></div><div class="dash-head"><div><div class="demo-kicker">LEARNING OVERVIEW</div><h3>Small steps.<br>Useful progress.</h3></div><span class="demo-tag">DEMO DATA</span></div><div class="stats"><div class="stat"><strong>12</strong><span>Sessions planned</span></div><div class="stat"><strong>8</strong><span>Complete</span></div><div class="stat"><strong>67%</strong><span>Completion · rounded</span></div></div><div class="progress-group"><h4>Your next step</h4><div class="progress-row"><span>Meeting notes → action</span><span>2 of 3 steps</span></div><div class="bar" role="img" aria-label="Two of three practice steps complete"><span style="width:66.6667%"></span></div></div><table class="dash-table"><caption class="sr-only">Illustrative learning sessions and status</caption><thead><tr><th scope="col">SESSION</th><th scope="col">STATUS</th><th scope="col">TIME</th></tr></thead><tbody><tr><td>Source-grounded summaries</td><td>Complete</td><td>10 min</td></tr><tr><td>Meeting notes into action</td><td>In progress</td><td>12 min</td></tr></tbody></table><small class="dash-note">Fictional metrics · 8 ÷ 12 = 66.7%, displayed as 67%</small></article>`;}
function example(view,mini=false){if(mini)return renderCard(true);let html=view==='page'?renderPage():view==='dashboard'?renderDashboard():['slide','jobaid','form','table'].includes(view)?renderExtra(view):renderCard();return customize(html,view);}
function drawGallery(){const selected=state.style;$('#style-grid').innerHTML=PROFILES.filter(p=>(state.category==='all'||p.category===state.category)&&(p.name+' '+p.summary+' '+p.typography).toLowerCase().includes(state.search.toLowerCase())).map(p=>`<article class="style-card ${selected===p.id?'active':''}"><div class="tile-preview ${p.id}" aria-hidden="true">${renderCard(true)}</div><div class="tile-info"><div class="tile-heading"><h3>${esc(p.name)}</h3><span class="style-number">${String(PROFILES.indexOf(p)+1).padStart(2,'0')}</span></div><p>${esc(p.summary)}</p><button type="button" class="tile-pick" data-select="${p.id}" aria-pressed="${selected===p.id}"><span>${selected===p.id?'Selected direction':'Explore this style'}</span><span aria-hidden="true">${selected===p.id?'✓':'↗'}</span></button></div></article>`).join('');$('#style-select').innerHTML=PROFILES.map(p=>`<option value="${p.id}" ${p.id===state.style?'selected':''}>${esc(p.name)}</option>`).join('');$('#selected-summary').textContent=PROFILES.find(p=>p.id===state.style).summary;const visible=PROFILES.filter(p=>(state.category==='all'||p.category===state.category)&&(p.name+' '+p.summary+' '+p.typography).toLowerCase().includes(state.search.toLowerCase())).length;$('#gallery-count').textContent=`${visible} of 25 styles`;$('#gallery-empty').hidden=visible>0;}
function drawStage(){if($('#audit-results'))$('#audit-results').textContent='Preview changed. Run checks to refresh the results.';const profiles=state.compare?state.compareStyles.map(id=>PROFILES.find(p=>p.id===id)):PROFILES.filter(p=>p.id===state.style);$('#stage').className='stage'+(state.compare?' compare':'');$('#stage').innerHTML=profiles.map(p=>`<div class="artboard ${p.id}"><span class="mini-label">${esc(p.name.toUpperCase())} / ${state.view.toUpperCase()}</span>${example(state.view)}</div>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===state.view)));$('#compare').setAttribute('aria-pressed',String(state.compare));applyBrand();$('#stage-caption').textContent=state.compare?'Same content · '+state.compareStyles.map(id=>PROFILES.find(p=>p.id===id).name).join(' / '):PROFILES.find(p=>p.id===state.style).name+' · '+({card:'Learning card',page:'Content page',dashboard:'Learning dashboard',slide:'Presentation slide',jobaid:'Job aid',form:'Request form',table:'Dense table'}[state.view]);document.body.classList.toggle('motion-on',state.motion&&settings.motion==='subtle'&&settings.format==='web');document.body.classList.toggle('hover-motion',state.motion&&settings.motion==='hover'&&settings.format==='web');$('#compare-controls').hidden=!state.compare;$('#compare-controls').innerHTML=state.compareStyles.map((id,i)=>`<label>Comparison ${i+1}<select aria-label="Comparison ${i+1}" data-compare-slot="${i}">${PROFILES.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`).join('');}
function drawProfile(){const p=PROFILES.find(p=>p.id===state.style);$('#profile-download').href=`profiles/${p.id}.json`;$('#profile-heading').textContent='The '+p.name.toLowerCase()+' profile.';$('#profile-body').innerHTML=`<div class="profile-layout"><article class="profile-facts"><h3 class="profile-name">${esc(p.name)}</h3><p class="profile-summary">${esc(p.summary)}</p><div class="palette">${Object.entries(p.tokens.colors).map(([name,color])=>`<div><div class="color-chip" style="background:${color}" aria-hidden="true"></div><div class="color-name">${name}</div><div class="color-hex">${color}</div></div>`).join('')}</div><div class="fact"><strong>Type & hierarchy</strong><p>${esc(p.typography)}</p></div><div class="fact"><strong>Where it works</strong><p>${esc(p.use_when)}</p></div><div class="fact"><strong>Use with care</strong><p>${esc(p.avoid_when)}</p></div><div class="fact"><strong>Keep / avoid</strong><p>${esc(p.essential_traits.join(' · '))}<br>Avoid: ${esc(p.exclude.join(' · '))}.</p></div></article><article class="prompt-box"><div class="prompt-title"><h3>Take it into your next task.</h3><button class="copy-btn" type="button" id="copy-prompt">Copy prompt ↗</button></div><p>Replace the bracketed fields. Bring your content and brand requirements with you.</p><pre class="prompt-text">${esc(productionPrompt(p))}</pre><div class="prompt-bottom"><a href="profiles/${p.id}.md" download>Download Markdown ↗</a><span>Profile v${p.version}</span></div></article></div>`;}
function render(){drawGallery();drawStage();drawProfile();}
document.addEventListener('click',async e=>{const select=e.target.closest('[data-select]');if(select){state.style=select.dataset.select;render();$('#style-select').focus({preventScroll:true});$('#studio').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return;}const tab=e.target.closest('[data-view]');if(tab){state.view=tab.dataset.view;drawStage();drawProfile();return;}if(e.target.closest('#compare')){state.compare=!state.compare;drawStage();return;}const demo=e.target.closest('[data-demo]');if(demo){if(demo.dataset.demo==='lesson'){state.view='page';drawStage();drawProfile();document.querySelector('[data-view="page"]').focus({preventScroll:true});notify('Content page opened. This is an illustrative lesson.');}else notify('Practice idea: use fictional notes to identify one action, a confirmed owner, and any missing deadline.');return;}if(e.target.closest('#copy-prompt')){const text=productionPrompt(PROFILES.find(p=>p.id===state.style));try{if(!navigator.clipboard)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text);notify('Prompt copied. Replace the bracketed fields before use.');}catch{const selection=window.getSelection();const range=document.createRange();range.selectNodeContents($('.prompt-text'));selection.removeAllRanges();selection.addRange(range);notify('Clipboard unavailable. Prompt selected—use your device’s Copy command.');}}});
$('#style-select').addEventListener('change',e=>{state.style=e.target.value;render();});
$('#style-search').addEventListener('input',e=>{state.search=e.target.value;drawGallery();});
$('#category-filter').addEventListener('change',e=>{state.category=e.target.value;drawGallery();});
$('#compare-controls').addEventListener('change',e=>{if(e.target.dataset.compareSlot!==undefined){const i=Number(e.target.dataset.compareSlot);state.compareStyles[i]=e.target.value;drawStage();document.querySelector(`[data-compare-slot="${i}"]`).focus({preventScroll:true});}});
$('#motion').addEventListener('change',e=>{state.motion=e.target.checked;drawStage();drawProfile();});
const defaults={title:'Turn meeting notes into action.',body:'A practical guide to clear next steps, visible owners, and better follow-through.',action:'View lesson',format:'web',brand:false,accent:'#234a3d',bg:'#ffffff',text:'#20332e',font:'inherit',motion:'subtle'};
const settings={...defaults};
const formatGuidance={web:'Responsive HTML with semantic structure, visible focus and reduced-motion support.',slides:'PowerPoint direction: editable text and shapes, 16:9 composition, 24 pt minimum body text; simplify effects. Preview is HTML, not a PPTX export.',documents:'Word / PDF direction: reading-first pages, headings, repeat table headers and printable contrast. Preview is HTML, not a DOCX or PDF export.',images:'Social direction: square composition, short headline, safe margins and a readable mobile hierarchy. Preview is HTML, not an exported image.'};
function customize(html,view){const t=document.createElement('template');t.innerHTML=html;const heading=t.content.querySelector('h3');if(heading)heading.textContent=settings.title;const para=t.content.querySelector('p');if(para)para.textContent=settings.body;else if(heading){const intro=document.createElement('p');intro.textContent=settings.body;heading.after(intro);}const button=t.content.querySelector('.demo-action');if(button)button.textContent=settings.action;return t.innerHTML;}
function renderExtra(view){const top='<div class="demo-kicker">AI AT WORK / FICTIONAL EXAMPLE</div><h3></h3><p></p>';if(view==='slide')return `<article class="demo-panel demo-slide">${top}<div class="slide-takeaway"><h4>Make the next step explicit.</h4><ul><li>Record the decision</li><li>Confirm an owner</li><li>Agree on a deadline</li></ul></div><small>01 / ACTIONABLE MEETINGS</small></article>`;if(view==='jobaid')return `<article class="demo-panel demo-jobaid">${top}<ol class="job-steps"><li><strong>Capture</strong> — separate discussion and decisions.</li><li><strong>Confirm</strong> — name the owner and next action.</li><li><strong>Check</strong> — mark missing dates for follow-up.</li><li><strong>Share</strong> — send the approved action list.</li></ol><aside class="callout">Stop and clarify any unsupported assignment.</aside></article>`;if(view==='form')return `<article class="demo-panel demo-form">${top}<form class="example-form"><label>Request summary<input required maxlength="120" placeholder="Example: confirm the next step"></label><label>Priority<select><option>Normal</option><option>High</option></select></label><label>Details<textarea rows="3" placeholder="Use fictional information"></textarea></label><button class="demo-action" type="submit">Send request</button><output class="form-result" role="status"></output><small>Demo only · nothing is sent or stored.</small></form></article>`;return `<article class="demo-panel demo-dense">${top}<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable fictional action table"><table class="dash-table"><caption>Fictional action tracker</caption><thead><tr>${['Action','Owner','Due','Priority','Status','Evidence'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${Array.from({length:8},(_,i)=>`<tr><th scope="row">${['Confirm decision','Draft summary','Review next steps','Share action list'][i%4]}</th><td>Team ${i+1}</td><td>Week ${i+1}</td><td>${i%2?'Normal':'High'}</td><td>${i%3?'Open':'Complete'}</td><td>Sample note ${i+1}</td></tr>`).join('')}</tbody></table></div></article>`;}
function applyBrand(){document.querySelectorAll('#stage .artboard').forEach(el=>{el.dataset.format=settings.format;if(settings.brand){for(const [k,v] of Object.entries({accent:settings.accent,bg:settings.bg,background:settings.bg,surface:settings.bg,text:settings.text,muted:settings.text}))el.style.setProperty('--'+k,v);if(settings.font!=='inherit'){el.style.fontFamily=settings.font;el.style.setProperty('--heading',settings.font);}el.querySelectorAll('.demo-panel').forEach(panel=>{panel.style.background=settings.bg;panel.style.color=settings.text;if(settings.font!=='inherit')panel.style.fontFamily=settings.font;});}});$('#format-note').textContent=formatGuidance[settings.format];$('#brand-conflicts').textContent=settings.brand?'Brand overrides profile colors'+(settings.font!=='inherit'?' and typography':'')+'. Structural style traits remain; color-led styles may look less distinctive. Run checks for contrast.':'Profile colors and typography are active.';}
function productionPrompt(p){return `${p.prompt}\n\nCURRENT PRODUCTION BRIEF\nHeadline: ${settings.title}\nBody: ${settings.body}\nAction: ${settings.action}\nExample layout: ${state.view}\nOutput: ${settings.format}. ${formatGuidance[settings.format]}\n${settings.brand?`Brand takes priority: accent ${settings.accent}; background ${settings.bg}; text ${settings.text}; font ${settings.font}. Flag any loss of essential style traits.`:'Use the profile palette and typography.'}\nMotion: ${state.motion?settings.motion:'none'}; always respect reduced motion. For static formats use no animation.\nPreserve supplied content and required visuals. Identify checks performed and limitations; do not claim an exported file exists until it has been created and verified.`;}
function syncInputs(){for(const [id,key] of Object.entries({'content-title':'title','content-body':'body','content-action':'action','output-format':'format','brand-accent':'accent','brand-bg':'bg','brand-text':'text','brand-font':'font','motion-treatment':'motion'}))$('#'+id).value=settings[key];$('#brand-enabled').checked=settings.brand;$('#motion').checked=state.motion;}
function refresh(){drawStage();drawProfile();$('#audit-results').textContent='Preview changed. Run checks to refresh the results.';}
for(const [id,key] of Object.entries({'content-title':'title','content-body':'body','content-action':'action','output-format':'format','brand-accent':'accent','brand-bg':'bg','brand-text':'text','brand-font':'font','motion-treatment':'motion'}))$('#'+id).addEventListener('input',e=>{settings[key]=e.target.value;refresh();});
$('#brand-enabled').addEventListener('change',e=>{settings.brand=e.target.checked;refresh();});
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Copied.');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();notify('Use your device Copy command.');area.addEventListener('blur',()=>area.remove(),{once:true});}}
function selectionURL(){const u=new URL(location.href);u.search='';u.hash='studio';u.searchParams.set('style',state.style);u.searchParams.set('view',state.view);u.searchParams.set('format',settings.format);u.searchParams.set('compare',state.compare?state.compareStyles.join(','):'');u.searchParams.set('motion',state.motion?settings.motion:'off');if(settings.brand){u.searchParams.set('brand',[settings.accent,settings.bg,settings.text].join(','));u.searchParams.set('font',settings.font);}return u.href;}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#share-selection').onclick=()=>copyText(selectionURL());
$('#download-brief').onclick=()=>download('design-production-brief.md',productionPrompt(PROFILES.find(p=>p.id===state.style)),'text/markdown');
$('#reset-content').onclick=()=>{for(const k of ['title','body','action'])settings[k]=defaults[k];syncInputs();refresh();};
$('#save-draft').onclick=()=>{try{localStorage.setItem('design-style-lab-v2',JSON.stringify({settings,state}));notify('Draft saved on this device.');}catch{notify('Device storage is unavailable. Download your brief instead.');}};
$('#load-draft').onclick=()=>{try{const saved=JSON.parse(localStorage.getItem('design-style-lab-v2'));if(!saved)throw Error();Object.assign(settings,saved.settings);Object.assign(state,saved.state);syncInputs();render();notify('Saved draft restored.');}catch{notify('No usable saved draft was found.');}};
function restoreURL(){const q=new URL(location.href).searchParams;const valid=id=>PROFILES.some(p=>p.id===id);if(valid(q.get('style')))state.style=q.get('style');if(['card','page','dashboard','slide','jobaid','form','table'].includes(q.get('view')))state.view=q.get('view');if(q.get('format') in formatGuidance)settings.format=q.get('format');const compare=(q.get('compare')||'').split(',');if(compare.length===3&&compare.every(valid)){state.compare=true;state.compareStyles=compare;}if(['subtle','hover','none'].includes(q.get('motion'))){state.motion=true;settings.motion=q.get('motion');}const brand=(q.get('brand')||'').split(',');if(brand.length===3&&brand.every(x=>/^#[0-9a-f]{6}$/i.test(x))){settings.brand=true;[settings.accent,settings.bg,settings.text]=brand;}if(['inherit','Arial, sans-serif','Georgia, serif','Verdana, sans-serif','monospace'].includes(q.get('font')))settings.font=q.get('font');}
// Composite background layers before evaluating contrast, including translucent panels.
function rgba(v){const n=v.match(/[\d.]+/g);return n?[+n[0],+n[1],+n[2],n[3]===undefined?1:+n[3]]:[0,0,0,0];}
function background(el){const layers=[];for(let n=el;n;n=n.parentElement)layers.unshift(rgba(getComputedStyle(n).backgroundColor));return layers.reduce((a,b)=>b.slice(0,3).map((v,i)=>v*b[3]+a[i]*(1-b[3])),[255,255,255]);}
function luminance(c){const v=c.slice(0,3).map(x=>{x/=255;return x<=.04045?x/12.92:((x+.055)/1.055)**2.4;});return v[0]*.2126+v[1]*.7152+v[2]*.0722;}
function audit(){let checked=0,low=0,small=0,effects=0;const problems=[];document.querySelectorAll('#stage .demo-panel *').forEach(el=>{if(!el.getClientRects().length)return;const cs=getComputedStyle(el);if(cs.backgroundImage!=='none'||cs.filter!=='none'||cs.backdropFilter&&cs.backdropFilter!=='none')effects++;if(![...el.childNodes].some(n=>n.nodeType===3&&n.textContent.trim()))return;const bg=background(el),fg=rgba(cs.color),rgb=fg.slice(0,3).map((v,i)=>v*fg[3]+bg[i]*(1-fg[3]));const a=luminance(rgb),b=luminance(bg),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);const size=parseFloat(cs.fontSize),large=size>=24||size>=18.66&&parseInt(cs.fontWeight)>=700;checked++;if(ratio<(large?3:4.5)){low++;if(problems.length<5)problems.push(el.textContent.trim().slice(0,50)+' ('+ratio.toFixed(2)+':1)');}if(size<14)small++;});effects += [...document.querySelectorAll('#stage .artboard')].filter(el=>getComputedStyle(el).backgroundImage!=='none').length;const controls=[...document.querySelectorAll('#stage button,#stage input,#stage select,#stage textarea')];const undersized=controls.filter(e=>{const r=e.getBoundingClientRect();return r.width<44||r.height<44;}).length;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;$('#audit-results').innerHTML=`<div class="audit-grid"><article><strong>${low?'Review':'Pass'} · text contrast</strong><p>${checked} text elements sampled; ${low} below 4.5:1 normal / 3:1 large text.</p>${problems.length?'<ul>'+problems.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}</article><article><strong>${small?'Review':'Pass'} · readability</strong><p>${small} text elements below the tool’s 14 px preview guideline. ${undersized} controls below 44 × 44 px.</p></article><article><strong>Motion & focus</strong><p>Device reduced motion: ${reduced?'on':'off'}. Decorative motion is suppressed when enabled. Visible keyboard focus rules are supplied; manually Tab through controls to verify order and visibility.</p></article></div><p>Unchecked: screen-reader experience, full keyboard operation, final exported files, image text and all responsive sizes. ${effects?'Effects detected: gradients, blur, filters and imagery require visual contrast review.':''} Contrast uses computed text color and composited solid background layers; effects are not pixel-sampled.</p>`;}
$('#run-audit').onclick=audit;
document.addEventListener('submit',e=>{if(e.target.matches('.example-form')){e.preventDefault();e.target.querySelector('.form-result').textContent='Demo complete. Your request was not sent.';}});
restoreURL();syncInputs();render();
